#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v;
    v.push_back({a});
    v.push_back({b});
    v.push_back({c});
    for (auto it = v.begin(); it != v.end(); ++it) {
        cout << *it << endl;
    }
    return 0;
}
